import 'dart:io';

/// The corpus's code-generation tool: writes an empty library naming the file
/// after `--input` to the path after `--output`, so `corpus_lib` builds from a
/// generated source without pulling a pub builder in.
void main(List<String> args) {
  final input = args[args.indexOf('--input') + 1];
  final output = args[args.indexOf('--output') + 1];
  File(output).writeAsStringSync(
    '// Generated by the corpus fixture generator from '
    '${input.split('/').last}.\n',
  );
}
